const { useState } = React;

function App() {
  const [formData, setFormData] = useState({ name: '', email: '', subject: '', message: '' });
  const [errors, setErrors] = useState({});
  const [page, setPage] = useState('contact');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: '' }));
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Name is required';
    if (!formData.email.trim()) newErrors.email = 'Email is required';
    if (!formData.subject.trim()) newErrors.subject = 'Subject is required';
    if (!formData.message.trim()) newErrors.message = 'Message is required';
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
    } else {
      alert('Form submitted successfully!');
      setFormData({ name: '', email: '', subject: '', message: '' });
      setErrors({});
    }
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
            Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
          background: #f9f7f1;
          color: #222;
        }
        header {
          border-bottom: 1px solid #ccc;
          padding: 1rem 2rem;
          display: flex;
          justify-content: space-between;
          align-items: center;
          background: #fff;
          font-style: italic;
          font-weight: 600;
          font-size: 1.25rem;
        }
        nav a {
          margin-left: 1.5rem;
          text-decoration: none;
          color: #222;
          font-style: italic;
          font-weight: 500;
          cursor: pointer;
          transition: color 0.2s ease;
        }
        nav a:hover {
          color: #0077cc;
        }
        main {
          display: flex;
          gap: 3rem;
          padding: 2rem;
          max-width: 900px;
          margin: 0 auto;
        }
        h1 {
          font-style: italic;
          font-weight: 600;
          border-bottom: 2px solid #222;
          padding-bottom: 0.25rem;
          margin-bottom: 1.5rem;
          font-size: 2rem;
        }
        form {
          flex: 1;
          display: flex;
          flex-direction: column;
          gap: 1rem;
        }
        input[type=text], input[type=email], textarea {
          font-style: italic;
          font-size: 1rem;
          padding: 0.5rem 0.75rem;
          border: 1.5px solid #999;
          border-radius: 4px;
          font-family: inherit;
          resize: vertical;
          transition: border-color 0.2s ease;
        }
        input[type=text]:focus, input[type=email]:focus, textarea:focus {
          outline: none;
          border-color: #0077cc;
          background: #fff;
        }
        textarea {
          min-height: 100px;
          font-style: italic;
        }
        button {
          width: 100px;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
          padding: 0.5rem 1rem;
          border: 1.5px solid #222;
          border-radius: 6px;
          background: #fff;
          cursor: pointer;
          transition: background-color 0.2s ease, color 0.2s ease;
          align-self: flex-start;
        }
        button:hover {
          background-color: #222;
          color: #fff;
        }
        .error {
          color: #b00020;
          font-size: 0.875rem;
          font-style: normal;
          margin-top: -0.75rem;
          margin-bottom: 0.5rem;
        }
        .right-side {
          flex: 1;
          font-style: italic;
          font-size: 1rem;
          display: flex;
          flex-direction: column;
          gap: 1rem;
          justify-content: flex-start;
        }
        .map-image {
          border: 1.5px solid #999;
          border-radius: 6px;
          width: 100%;
          height: 180px;
          object-fit: cover;
          background: #ddd;
        }
        .contact-info {
          line-height: 1.5;
          white-space: pre-line;
        }
        .services-list {
          font-style: italic;
          font-size: 1rem;
          line-height: 1.5;
          padding-right: 1rem;
        }
      `}</style>
      <header>
        <div>Acme</div>
        <nav aria-label="Primary">
          <a href="#home" onClick={(e) => { e.preventDefault(); setPage('contact'); }}>Home</a>
          <a href="#services" onClick={(e) => { e.preventDefault(); setPage('services'); }}>Services</a>
          <a href="#contact" onClick={(e) => { e.preventDefault(); setPage('contact'); }}>Contact</a>
        </nav>
      </header>
      <main>
        {page === 'contact' && (
          <>
            <section aria-labelledby="contact-heading">
              <h1 id="contact-heading">Get in touch</h1>
              <form onSubmit={handleSubmit} noValidate>
                <label htmlFor="name">
                  <input
                    type="text"
                    id="name"
                    name="name"
                    placeholder="Name"
                    value={formData.name}
                    onChange={handleChange}
                    aria-describedby={errors.name ? 'name-error' : undefined}
                    aria-invalid={errors.name ? 'true' : 'false'}
                  />
                </label>
                {errors.name && (
                  <div id="name-error" role="alert" className="error">
                    {errors.name}
                  </div>
                )}

                <label htmlFor="email">
                  <input
                    type="email"
                    id="email"
                    name="email"
                    placeholder="Email"
                    value={formData.email}
                    onChange={handleChange}
                    aria-describedby={errors.email ? 'email-error' : undefined}
                    aria-invalid={errors.email ? 'true' : 'false'}
                  />
                </label>
                {errors.email && (
                  <div id="email-error" role="alert" className="error">
                    {errors.email}
                  </div>
                )}

                <label htmlFor="subject">
                  <input
                    type="text"
                    id="subject"
                    name="subject"
                    placeholder="Subject"
                    value={formData.subject}
                    onChange={handleChange}
                    aria-describedby={errors.subject ? 'subject-error' : undefined}
                    aria-invalid={errors.subject ? 'true' : 'false'}
                  />
                </label>
                {errors.subject && (
                  <div id="subject-error" role="alert" className="error">
                    {errors.subject}
                  </div>
                )}

                <label htmlFor="message">
                  <textarea
                    id="message"
                    name="message"
                    placeholder="Message"
                    value={formData.message}
                    onChange={handleChange}
                    aria-describedby={errors.message ? 'message-error' : undefined}
                    aria-invalid={errors.message ? 'true' : 'false'}
                  />
                </label>
                {errors.message && (
                  <div id="message-error" role="alert" className="error">
                    {errors.message}
                  </div>
                )}

                <button type="submit">Submit</button>
              </form>
            </section>
            <aside className="right-side" aria-label="Contact details and map">
              <img
                src="/runtime/photos/building.jpg"
                alt="Map location"
                className="map-image"
                aria-hidden="true"
              />
              <address className="contact-info">
                123 Main St, Springfield
                <br />
                +1 555 0100
                <br />
                <a href="mailto:hello@acme.com">hello@acme.com</a>
              </address>
            </aside>
          </>
        )}
        {page === 'services' && (
          <section aria-labelledby="services-heading" style={{ flex: 1 }}>
            <h1 id="services-heading">Our Services</h1>
            <p className="services-list">
              We offer a wide range of services to meet your needs:
            </p>
            <ul className="services-list">
              <li>Consulting and Strategy</li>
              <li>Product Design and Development</li>
              <li>Marketing and Branding</li>
              <li>Customer Support and Training</li>
              <li>Custom Software Solutions</li>
            </ul>
          </section>
        )}
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

